part of '../../library_vkid.dart';

/// A type of One Tap, specifies the theme.
enum OneTapType {
  /// A type for One Tap with the light theme.
  light,

  /// A type for One Tap with the dark theme.
  dark,

  /// A type for One Tap with the light theme and transparent background.
  transparentLight,

  /// A type for One Tap with the dark theme and transparent background.
  transparentDark,

  /// An icon type of One Tap.
  icon,

  /// A type for One Tap with a theme which corresponds to the current theme in system settings.
  system,

  /// A type for One Tap with a theme which corresponds to the current theme in system settings and transparent background.
  transparentSystem,
}
